            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterH = (((aWandererA + RotL64(aCross, 11U)) + RotL64(aCarry, 29U)) + 0xB5E2FA5B2A9C6A7BULL) + aTwistOrbiterAssignSaltC[((aIndex + 239U)) & S_SALT1];
            aOrbiterJ = ((aWandererD + RotL64(aScatter, 4U)) + RotL64(aCarry, 13U)) + 0x7DE77190BBE2C085ULL;
            aOrbiterG = (aWandererH + RotL64(aPrevious, 41U)) + 0x66C3A87C9C63CCC8ULL;
            aOrbiterA = (aWandererB + RotL64(aIngress, 29U)) + 0x7B2136DE93BE1671ULL;
            aOrbiterB = ((aWandererK + RotL64(aCross, 35U)) + 0x35E9A1BC96C6B322ULL) + aTwistOrbiterAssignSaltA[((aIndex + 178U)) & S_SALT1];
            aOrbiterF = ((aWandererF + RotL64(aIngress, 53U)) + RotL64(aCarry, 47U)) + 0xE7758C44AF63CBC0ULL;
            aOrbiterD = (aWandererG + RotL64(aScatter, 19U)) + 0x7B079042475D3D1AULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0xB942251512EC52DAULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0xC1372321A67C9F96ULL;
