            aOrbiterJ = RotL64((aOrbiterJ * 0xC2C7F4AA9E6A7AEFULL), 3U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterG) + 0xCDCB268636DFB9F5ULL) + aTwistOrbiterUpdateSaltA[(((255U - aIndex) + 198U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterJ) ^ 0x8A683E8D99537F28ULL) ^ aTwistOrbiterUpdateSaltC[(((255U - aIndex) + 75U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x1E7145419D077765ULL), 35U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0xBAF5E6B81B92855CULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xFC2AA99BAC22CF59ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x7F58271CEDA79E99ULL), 43U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterA) + 0x55F4D573B7D3035CULL) + aTwistOrbiterUpdateSaltE[(((255U - aIndex) + 145U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x771881133DC3C0C5ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xC1639B0F333F31A1ULL), 11U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0xF821F6219C4C06C5ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterF) ^ 0x97DD0CFD81586AE5ULL) ^ aTwistOrbiterUpdateSaltD[(((255U - aIndex) + 73U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xE66995198895F5F1ULL), 51U);
            //
            aIngress = RotL64(aOrbiterA, 27U) ^ aOrbiterH;
            aIngress = aIngress + (RotL64(aOrbiterG, 19U) ^ aOrbiterB);
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterJ, 4U));
            aIngress = aIngress + RotL64(aOrbiterF, 13U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererA = aWandererA ^ ((RotL64(aPrevious, 37U) + aOrbiterJ) + RotL64(aOrbiterA, 3U));
            aWandererG = aWandererG + (((RotL64(aCross, 5U) + RotL64(aOrbiterH, 11U)) + aOrbiterG) + RotL64(aCarry, 41U));
            aWandererF = aWandererF ^ ((RotL64(aScatter, 48U) + RotL64(aOrbiterG, 57U)) + aOrbiterA);
            aWandererK = aWandererK + ((((RotL64(aIngress, 29U) + RotL64(aOrbiterH, 19U)) + aOrbiterD) + RotL64(aCarry, 19U)) + aTwistWandererUpdateSaltF[((aIndex + 82U)) & S_SALT1]);
