            aWandererB = aWandererB + (((RotL64(aScatter, 21U) + RotL64(aOrbiterD, 28U)) + aOrbiterF) + aTwistWandererUpdateSaltD[((aIndex + 7U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 13U) + RotL64(aOrbiterA, 51U)) + aOrbiterF);
