            aOrbiterJ = ((aWandererF + RotL64(aIngress, 23U)) + RotL64(aCarry, 13U)) + 0x34E8B5988AC32A21ULL;
            aOrbiterK = (aWandererB + RotL64(aPrevious, 52U)) + 0x9325E705F3F14D07ULL;
            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0x8EF7AFA73105BBEAULL) + aTwistOrbiterUpdateSaltB[(((255U - aIndex) + 82U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x2BE4FDF40C6ACA24ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xC76DECDE1F3E69E3ULL), 51U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0xBDDD2495D0C9799DULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterA) ^ 0xA99563E276FE055FULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 213U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xDAD0CC232F0E2331ULL), 19U);
