            //
            aOrbiterB = ((aOrbiterB + aOrbiterK) + 0x7C368AC9AE50AAD2ULL) + aTwistOrbiterUpdateSaltF[(((255U - aIndex) + 173U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0xC9F8861F744E87B0ULL;
