            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x4BF0C85BE79A1E10ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterI) ^ 0x577F309BDF7B59C3ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((255U - aIndex) + 67U)) & S_SALT1];
