            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0xC2F8B864974F5B59ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x96E82E7AECDD57CFULL;
            aOrbiterB = RotL64((aOrbiterB * 0xE0F3B228F61950B1ULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x4B405DF0DA1613E2ULL;
