            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterH) + 0xEDE9639A8F264593ULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 56U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x1E9C7424F14ACC84ULL;
